DB_PATH=os.getenv('FINANCE_DB_PATH',os.path.join('data','finance_currency.sqlite3'))

class CurrencyEngine:
    def __init__(self,db_path=DB_PATH):
        os.makedirs(os.path.dirname(db_path) or '.',exist_ok=True); self.db_path=db_path
        with self._db() as c:
            c.execute('CREATE TABLE IF NOT EXISTS exchange_rates(rate_id TEXT PRIMARY KEY,base_currency TEXT NOT NULL,quote_currency TEXT NOT NULL,rate REAL NOT NULL,source TEXT NOT NULL,observed_at TEXT NOT NULL)')
            c.execute('CREATE TABLE IF NOT EXISTS conversion_audit(conversion_id TEXT PRIMARY KEY,base_currency TEXT NOT NULL,quote_currency TEXT NOT NULL,source_amount REAL NOT NULL,converted_amount REAL NOT NULL,rate REAL NOT NULL,rate_source TEXT NOT NULL,converted_at TEXT NOT NULL)')
    def _db(self):
        c=sqlite3.connect(self.db_path); c.row_factory=sqlite3.Row; return c
    def metadata(self,code=None):
        if code:
            code=code.upper()
            if code not in CURRENCIES: raise ValueError('unsupported_currency')
            return {'code':code,**CURRENCIES[code]}
        return {k:{'code':k,**v} for k,v in CURRENCIES.items()}
    def set_rate(self,base_currency,quote_currency,rate,source,observed_at=None):
        base,quote=base_currency.upper(),quote_currency.upper()
        if base not in CURRENCIES or quote not in CURRENCIES: raise ValueError('unsupported_currency')
        if float(rate)<=0 or not source: raise ValueError('invalid_exchange_rate')
        rid='RATE-'+datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S%f'); ts=observed_at or datetime.now(timezone.utc).isoformat()
        with self._db() as c: c.execute('INSERT INTO exchange_rates VALUES(?,?,?,?,?,?)',(rid,base,quote,float(rate),str(source),ts))
        return {'rate_id':rid,'base_currency':base,'quote_currency':quote,'rate':float(rate),'source':str(source),'observed_at':ts}
    def convert(self,amount,base_currency,quote_currency,rate,source):
        base,quote=base_currency.upper(),quote_currency.upper()
        if base not in CURRENCIES or quote not in CURRENCIES: raise ValueError('unsupported_currency')
        if float(rate)<=0 or not source: raise ValueError('conversion_rate_required')
        converted=float(amount)*float(rate); cid='CONV-'+datetime.now(timezone.utc).strftime('%Y%m%d%H%M%S%f'); ts=datetime.now(timezone.utc).isoformat()
        with self._db() as c: c.execute('INSERT INTO conversion_audit VALUES(?,?,?,?,?,?,?,?)',(cid,base,quote,float(amount),converted,float(rate),str(source),ts))
        return {'conversion_id':cid,'source_amount':float(amount),'source_currency':base,'converted_amount':converted,'converted_currency':quote,'rate':float(rate),'rate_source':str(source),'converted_at':ts}
    def health(self):
        with self._db() as c: rates=c.execute('SELECT COUNT(*) FROM exchange_rates').fetchone()[0]
        return {'status':'ok','engine':'currency-finance','currencies_supported':len(CURRENCIES),'exchange_rates':rates,'source_amounts_immutable':True,'tax_jurisdiction_explicit':True}
